// ═══ Arrays.asList: fixed-size, backed by array ═══
String[] arr = {"SAV2001", "CUR3001", "FD4001"};
List<String> list = Arrays.asList(arr);

list.set(0, "CHANGED");     // (Recommended) writes through to array!
arr[0];                       // "CHANGED" — array changed too!
// list.add("NEW");          // (Avoid) UnsupportedOperationException (fixed size!)
// list.remove(0);           // (Avoid) UnsupportedOperationException (fixed size!)
list.contains(null);          // (Recommended) null allowed

// Array changes reflect in list:
arr[1] = "MODIFIED";
list.get(1);                  // "MODIFIED" — list sees array change!

// ═══ List.of: truly immutable ═══
List<String> immutable = List.of("SAV2001", "CUR3001");
// immutable.set(0, "X");   // (Avoid) UnsupportedOperationException!
// immutable.add("X");      // (Avoid) UnsupportedOperationException!
// List.of(null);            // (Avoid) NullPointerException!

// ═══ PRIMITIVE ARRAY GOTCHA ═══
int[] primitiveArr = {1, 2, 3};
List<int[]> wrong = Arrays.asList(primitiveArr);
wrong.size();  // 1! Not 3! The int[] is treated as ONE element!
// Because: asList(T...) → T = int[] → List<int[]> with 1 element!

// FIX 1: use Integer[]
Integer[] boxedArr = {1, 2, 3};
List<Integer> correct1 = Arrays.asList(boxedArr);  // size 3! (Recommended) 

// FIX 2: stream + boxed
List<Integer> correct2 = Arrays.stream(primitiveArr).boxed().toList();  // size 3! (Recommended) 

// ═══ MAKING A MUTABLE COPY ═══
List<String> mutable = new ArrayList<>(Arrays.asList("A", "B", "C"));
mutable.add("D");  // (Recommended) works! New ArrayList, not backed by array.
