package com.bank.aslist;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class AsListVsListOfTest {

    @Test
    void asList_fixedSize_setAllowed() {
        String[] arr = {"A", "B", "C"};
        List<String> list = Arrays.asList(arr);
        list.set(0, "Z");
        assertThat(arr[0]).isEqualTo("Z");  // array changed!
        assertThatThrownBy(() -> list.add("D"))
            .isInstanceOf(UnsupportedOperationException.class);
    }

    @Test
    void asList_backedByArray() {
        String[] arr = {"A", "B"};
        List<String> list = Arrays.asList(arr);
        arr[1] = "MODIFIED";
        assertThat(list.get(1)).isEqualTo("MODIFIED");  // list sees array change!
    }

    @Test
    void listOf_trulyImmutable() {
        List<String> list = List.of("A", "B");
        assertThatThrownBy(() -> list.set(0, "Z"))
            .isInstanceOf(UnsupportedOperationException.class);
    }

    @Test
    void primitiveArrayGotcha() {
        int[] primitives = {1, 2, 3};
        List<int[]> wrong = Arrays.asList(primitives);
        assertThat(wrong).hasSize(1);  // 1! Not 3! Whole array is one element!

        Integer[] boxed = {1, 2, 3};
        List<Integer> correct = Arrays.asList(boxed);
        assertThat(correct).hasSize(3);  // 3! (Recommended) 
    }

    @Test
    void primitiveArray_streamFix() {
        int[] primitives = {1, 2, 3};
        List<Integer> correct = Arrays.stream(primitives).boxed().toList();
        assertThat(correct).containsExactly(1, 2, 3);
    }
}
